head.script:
scwin.onpageload = function() {
    var jsonData = [{
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        },
        {
            "col1": "1111",
            "col2": "2222",
            "col3": "3333",
            "col4": "4444"
        }
    ];
    dataList1.setJSON(jsonData);
    scwin.init = function() {
        gridView1.hide();
    };
};
scwin.init = function() {
    gridView1.hide();
};
scwin.onpageunload = function() {};
scwin.isIgnoreKey = function(e) {
    var ignoreKey = false;
    if (e.ctrlKey) {
        switch (e.keyCode) {
            case 88:
                ignoreKey = true;
                break; //grid에서 ctrl+x key 처리하지 않도록 함   //Keyboard.X
        }
    }
    return ignoreKey;
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.setSimulate1 = function() {
    WebSquare.wUnit.getJq('#gridView1_cell_0_0').simulate('key-combo', {
        combo: 'ctrl+x'
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 1. 샘플 실행 후 콘솔을 열고 name1항목의 첫번째 값을 20179999로 수정 후 tab key로 이동한다.
    //1. After running the sample, open console and change the first value of name1 item to 20179999 and move to tab key.
    //Verify step 1. The value of cell is automatically changed to an empty value like ''.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_cell_0_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#gridView1_cell_0_0').text() == '1111'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
